package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"os"
	"testing"
	"time"
)

func TestDictionaryBrowser(t *testing.T) {
	if os.Getenv("GNOTES_BROWSER_CHECK") != "1" {
		t.Skip("optional local Chromium check")
	}
	for _, width := range []int{320, 1024} {
		t.Run(fmt.Sprint(width), func(t *testing.T) {
			recoveryFixture(t)
			mustRecoveryExec(t, "INSERT INTO notes (user_id,title,content,created_at) VALUES (1,'Dictionary note',?,?)", "Serendipity makes engineering interesting.\nChildren learn by running.", time.Now().UTC())
			mux := http.NewServeMux()
			mux.HandleFunc("/api/auth/config", authConfigHandler)
			mux.HandleFunc("/api/auth/login", loginHandler)
			mux.HandleFunc("/api/auth/me", protect(meHandler, false))
			mux.HandleFunc("/api/auth/logout", protect(logoutHandler, true))
			mux.HandleFunc("/api/draft", protect(getDraftHandler, false))
			mux.HandleFunc("/api/draft/update", protect(updateDraftHandler, true))
			mux.HandleFunc("/api/draft/finalize", protect(finalizeDraftHandler, true))
			mux.HandleFunc("/api/notes/page", protect(pagedListNotesHandler, false))
			mux.HandleFunc("/api/notes/trash-page", protect(pagedTrashNotesHandler, false))
			mux.HandleFunc("/api/notes/update", protect(updateNoteHandler, true))
			mux.HandleFunc("/api/tags", protect(tagsHandler, false))
			registerDictionaryRoutes(mux)
			mux.Handle("/", http.FileServer(http.Dir("../../public")))
			server := httptest.NewServer(securityHeaders(mux))
			defer server.Close()
			browser := newRecoveryBrowser(t)
			browser.call("POST", "/goog/cdp/execute", map[string]any{"cmd": "Emulation.setDeviceMetricsOverride", "params": map[string]any{"width": width, "height": 800, "deviceScaleFactor": 1, "mobile": false}})
			click := func(selector string) {
				t.Helper()
				t.Log("click", selector)
				node := browser.call("POST", "/element", map[string]string{"using": "css selector", "value": selector}).(map[string]any)
				browser.call("POST", "/element/"+node["element-6066-11e4-a52e-4f735466cecf"].(string)+"/click", nil)
			}
			browser.navigate(server.URL)
			browser.wait(`!document.getElementById('auth-screen').hidden && Boolean(window.GnotesDictionary)`)
			browser.script(`document.getElementById('auth-username').value='rick'; document.getElementById('auth-password').value='original password'; document.getElementById('auth-form').requestSubmit();`)
			browser.wait(`!notesLoading && !document.getElementById('app-shell').hidden && document.querySelectorAll('.note-card').length===1`)
			browser.call("POST", "/goog/cdp/execute", map[string]any{"cmd": "Browser.grantPermissions", "params": map[string]any{"origin": server.URL, "permissions": []string{"clipboardReadWrite", "clipboardSanitizedWrite"}}})
			rightClickTitle := func(selectAll bool) {
				t.Helper()
				point := browser.script(fmt.Sprintf(`const title=document.querySelector('.note-view > h2');title.scrollIntoView({block:'center'});const range=document.createRange();range.setStart(title.firstChild,0);range.setEnd(title.firstChild,10);const selection=getSelection();selection.removeAllRanges();if(%t){range.selectNodeContents(title);selection.addRange(range);}const r=range.getBoundingClientRect();return [Math.round((r.left+r.right)/2),Math.round((r.top+r.bottom)/2)];`, selectAll)).([]any)
				browser.call("POST", "/actions", map[string]any{"actions": []any{map[string]any{"type": "pointer", "id": "title-right-click", "parameters": map[string]string{"pointerType": "mouse"}, "actions": []any{map[string]any{"type": "pointerMove", "duration": 0, "x": point[0], "y": point[1]}, map[string]any{"type": "pointerDown", "button": 2}, map[string]any{"type": "pointerUp", "button": 2}}}}})
				browser.wait(`!document.getElementById('note-context-menu').hidden && !document.getElementById('dictionary-dialog').open`)
			}
			rightClickTitle(true)
			click("#note-context-copy")
			browser.wait(`document.getElementById('note-action-toast').textContent==='Copied'`)
			browser.script(`navigator.clipboard.readText().then(text=>window.titleCopied=text==='Dictionary note');`)
			browser.wait(`window.titleCopied===true`)
			rightClickTitle(false)
			click("#note-context-dictionary")
			browser.wait(`document.getElementById('dictionary-dialog').open && document.getElementById('dictionary-word').value==='dictionary' && document.querySelectorAll('#dictionary-result li').length>0`)
			click("#dictionary-close")
			rightClickTitle(false)
			click("#note-context-ignore")
			browser.wait(`!spellingBusy && ignoredSpellingWords.includes('dictionary')`)
			// A draft title's selected text uses the same menu without creating a note.
			browser.script(`const input=document.getElementById('title');input.value='Acme Corporation';input.focus();input.setSelectionRange(0,4);input.dispatchEvent(new MouseEvent('contextmenu',{bubbles:true,cancelable:true,clientX:20,clientY:100}));`)
			click("#note-context-copy")
			browser.script(`navigator.clipboard.readText().then(text=>window.draftTitleCopied=text==='Acme');`)
			browser.wait(`window.draftTitleCopied===true`)
			browser.script(`document.getElementById('title').value='';getSelection().removeAllRanges();`)
			// A phone long press must remain available to native selection/Copy.
			browser.script(`const p=document.querySelector('.note-content p');const node=p.firstChild;const r=document.createRange();r.setStart(node,0);r.setEnd(node,11);getSelection().addRange(r);p.dispatchEvent(new PointerEvent('pointerdown',{bubbles:true,pointerType:'touch'}));const e=new PointerEvent('contextmenu',{bubbles:true,cancelable:true,pointerType:'touch'});p.dispatchEvent(e);if(e.defaultPrevented||!document.getElementById('note-context-menu').hidden||getSelection().toString()!=='Serendipity')throw new Error('Long press blocked native text selection');p.dispatchEvent(new PointerEvent('pointerdown',{bubbles:true,pointerType:'mouse'}));getSelection().removeAllRanges();`)
			browser.call("POST", "/goog/cdp/execute", map[string]any{"cmd": "Emulation.setTouchEmulationEnabled", "params": map[string]any{"enabled": true, "maxTouchPoints": 1}})
			browser.script(`if(!matchMedia('(hover: none) and (pointer: coarse)').matches)throw new Error('Phone emulation requires a coarse pointer');const e=new MouseEvent('contextmenu',{bubbles:true,cancelable:true});document.querySelector('.note-content p').dispatchEvent(e);if(e.defaultPrevented||!document.getElementById('note-context-menu').hidden)throw new Error('Phone MouseEvent blocked native selection');`)
			// A mouse remains usable on touch laptops and after a touchscreen tap.
			browser.script(`const input=document.getElementById('title');input.value='Acme Corporation';input.focus();input.setSelectionRange(0,4);input.dispatchEvent(new PointerEvent('pointerdown',{bubbles:true,pointerType:'touch'}));const e=new PointerEvent('contextmenu',{bubbles:true,cancelable:true,pointerType:'mouse',button:2});input.dispatchEvent(e);if(!e.defaultPrevented||document.getElementById('note-context-menu').hidden)throw new Error('Touch detection suppressed mouse context menu');if(document.querySelectorAll('#note-context-menu button').length!==3)throw new Error('Expected three context actions');const native=new PointerEvent('contextmenu',{bubbles:true,cancelable:true,pointerType:'mouse',button:2,shiftKey:true});input.dispatchEvent(native);if(native.defaultPrevented||!document.getElementById('note-context-menu').hidden)throw new Error('Shift right-click must keep the native menu');input.dispatchEvent(new PointerEvent('pointerdown',{bubbles:true,pointerType:'mouse'}));input.focus();input.setSelectionRange(0,4);const legacy=new MouseEvent('contextmenu',{bubbles:true,cancelable:true,button:2});input.dispatchEvent(legacy);if(!legacy.defaultPrevented||document.getElementById('note-context-menu').hidden)throw new Error('Touch detection suppressed legacy mouse context menu');input.dispatchEvent(native);input.value='';input.blur();getSelection().removeAllRanges();`)
			browser.call("POST", "/goog/cdp/execute", map[string]any{"cmd": "Emulation.setTouchEmulationEnabled", "params": map[string]any{"enabled": false}})
			point := browser.script(`const p=document.querySelector('.note-content p'); p.scrollIntoView({block:'center'}); const range=document.createRange(); range.setStart(p.firstChild,2); range.setEnd(p.firstChild,5); const rect=range.getBoundingClientRect(); return [Math.round((rect.left+rect.right)/2),Math.round((rect.top+rect.bottom)/2)];`).([]any)
			browser.call("POST", "/actions", map[string]any{"actions": []any{map[string]any{"type": "pointer", "id": "dictionary-right-click", "parameters": map[string]string{"pointerType": "mouse"}, "actions": []any{map[string]any{"type": "pointerMove", "duration": 0, "x": point[0], "y": point[1]}, map[string]any{"type": "pointerDown", "button": 2}, map[string]any{"type": "pointerUp", "button": 2}}}}})
			browser.wait(`!document.getElementById('note-context-menu').hidden && !document.getElementById('dictionary-dialog').open`)
			click("#note-context-dictionary")
			browser.wait(`document.getElementById('dictionary-dialog').open && document.getElementById('dictionary-word').value==='serendipity' && document.querySelectorAll('#dictionary-result li').length>0`)
			click("#dictionary-ignore")
			browser.wait(`ignoredSpellingWords.includes('serendipity') && document.getElementById('dictionary-save').textContent==='Save word'`)
			browser.script(`const r=document.getElementById('dictionary-dialog').getBoundingClientRect(); if(r.left<0 || r.right>innerWidth || r.top<0 || r.bottom>innerHeight || document.documentElement.scrollWidth>innerWidth) throw new Error('Dictionary modal overflows'); if(document.querySelector('#dictionary-result script')) throw new Error('Definition must be text');`)
			click("#dictionary-save")
			browser.wait(`document.getElementById('dictionary-save').textContent==='Remove saved word' && !document.getElementById('dictionary-save').disabled`)
			click("#dictionary-saved-tab")
			browser.wait(`document.querySelectorAll('#dictionary-word-list li').length===1 && document.querySelector('[data-lookup-word="serendipity"]')`)
			click("#dictionary-close")
			// Selected text in a displayed note exposes Dictionary on mobile too.
			browser.script(`const node=document.querySelector('.note-content p').firstChild; const start=node.textContent.indexOf('engineering'); const range=document.createRange();range.setStart(node,start);range.setEnd(node,start+11);const selection=getSelection();selection.removeAllRanges();selection.addRange(range);`)
			browser.wait(`!document.getElementById('dictionary-selection').hidden`)
			if width == 320 {
				browser.script(`const bar=document.getElementById('note-selection-actions'),r=bar.getBoundingClientRect();if(!bar.classList.contains('is-docked')||document.getElementById('selection-ignore').hidden||r.left<0||r.right>innerWidth||r.bottom>innerHeight||r.top<innerHeight-100)throw new Error('Phone actions must dock at the bottom');if(getSelection().toString()!=='engineering')throw new Error('Bottom bar changed native selection');`)
			}
			if width == 320 {
				point := browser.script(`const r=document.getElementById('dictionary-selection').getBoundingClientRect();return [Math.round((r.left+r.right)/2),Math.round((r.top+r.bottom)/2)];`).([]any)
				browser.call("POST", "/actions", map[string]any{"actions": []any{map[string]any{"type": "pointer", "id": "word-action-tap", "parameters": map[string]string{"pointerType": "touch"}, "actions": []any{map[string]any{"type": "pointerMove", "duration": 0, "x": point[0], "y": point[1]}, map[string]any{"type": "pointerDown", "button": 0}, map[string]any{"type": "pointerUp", "button": 0}}}}})
			} else {
				click("#dictionary-selection")
			}
			browser.wait(`document.getElementById('dictionary-word').value==='engineering' && document.querySelectorAll('#dictionary-result li').length>0`)
			click("#dictionary-save")
			browser.wait(`document.getElementById('dictionary-save').textContent==='Remove saved word' && !document.getElementById('dictionary-save').disabled`)
			click("#dictionary-close")
			// The editor's Dictionary button must preserve the active note.
			browser.script(`window.dictNoteID=Number(document.querySelector('.note-card').id.slice(5));openNoteEditor(dictNoteID,false);`)
			browser.wait(`Boolean(richEdit)`)
			browser.script(`const input=document.getElementById('edit-title-'+dictNoteID);input.focus();input.setSelectionRange(0,10);input.dispatchEvent(new MouseEvent('contextmenu',{bubbles:true,cancelable:true,clientX:20,clientY:100}));`)
			click("#note-context-dictionary")
			browser.wait(`document.getElementById('dictionary-dialog').open && document.getElementById('dictionary-word').value==='dictionary' && document.querySelectorAll('#dictionary-result li').length>0`)
			browser.script(`if(editingNoteId!==dictNoteID||document.getElementById('edit-title-'+dictNoteID).value!=='Dictionary note')throw new Error('Title menu closed or changed the editor');`)
			click("#dictionary-close")
			browser.script(`if(!richEdit.editor.view.dom.querySelector('[data-spelling-ignored]') || richEdit.getMarkdown().includes('spellcheck')) throw new Error('Ignoring must decorate without altering note content');`)
			// Exercise an actual secondary click in the rich editor, not only a
			// dispatched event with a preselected word.
			editorPoint := browser.script(`richEdit.editor.chain().focus().setTextSelection(1).run();const p=richEdit.editor.view.dom.querySelector('p');p.scrollIntoView({block:'center'});const node=document.createTreeWalker(p,NodeFilter.SHOW_TEXT).nextNode();const range=document.createRange();range.setStart(node,2);range.setEnd(node,5);const r=range.getBoundingClientRect();return [Math.round((r.left+r.right)/2),Math.round((r.top+r.bottom)/2)];`).([]any)
			browser.call("POST", "/actions", map[string]any{"actions": []any{map[string]any{"type": "pointer", "id": "editor-right-click", "parameters": map[string]string{"pointerType": "mouse"}, "actions": []any{map[string]any{"type": "pointerMove", "duration": 0, "x": editorPoint[0], "y": editorPoint[1]}, map[string]any{"type": "pointerDown", "button": 2}, map[string]any{"type": "pointerUp", "button": 2}}}}})
			browser.wait(`!document.getElementById('note-context-menu').hidden && !document.getElementById('note-context-dictionary').disabled`)
			click("#note-context-dictionary")
			browser.wait(`document.getElementById('dictionary-dialog').open && document.getElementById('dictionary-word').value==='serendipity'`)
			click("#dictionary-close")
			browser.script(`richEdit.editor.chain().focus().setTextSelection(1).run();const root=richEdit.editor.view.dom,r=root.getBoundingClientRect();const e=new MouseEvent('contextmenu',{bubbles:true,cancelable:true,button:2,clientX:r.right-2,clientY:r.bottom-2});root.dispatchEvent(e);if(!e.defaultPrevented||document.getElementById('note-context-menu').hidden)throw new Error('Editor whitespace must show text actions');`)
			browser.script(`applyEditorMode(true);const input=document.getElementById('edit-content-'+dictNoteID);input.focus();input.setSelectionRange(0,11);const e=new MouseEvent('contextmenu',{bubbles:true,cancelable:true,button:2});input.dispatchEvent(e);if(!e.defaultPrevented||document.getElementById('note-context-menu').hidden)throw new Error('Source editor must show text actions');`)
			click("#note-context-copy")
			browser.script(`navigator.clipboard.readText().then(text=>window.sourceCopied=text==='Serendipity');`)
			browser.wait(`window.sourceCopied===true && editingNoteId===dictNoteID`)
			browser.script(`const input=document.getElementById('edit-content-'+dictNoteID);input.focus();input.setSelectionRange(0,11);window.sourceCopied=false;`)
			click(".is-editing .edit-copy")
			browser.script(`navigator.clipboard.readText().then(text=>window.sourceCopied=text==='Serendipity');`)
			browser.wait(`window.sourceCopied===true && editingNoteId===dictNoteID`)
			browser.script(`const input=document.getElementById('edit-content-'+dictNoteID);input.focus();input.setSelectionRange(0,0);window.expectedFullCopy=document.getElementById('edit-title-'+dictNoteID).value+'\n\n'+input.value.trim();`)
			click(".is-editing .edit-copy")
			browser.script(`navigator.clipboard.readText().then(text=>window.sourceFullCopied=text===expectedFullCopy);`)
			browser.wait(`window.sourceFullCopied===true`)
			browser.script(`applyEditorMode(false);`)
			browser.script(`richEdit.editor.chain().focus().setTextSelection({from:1,to:12}).run();`)
			click(".is-editing .edit-copy")
			browser.script(`navigator.clipboard.readText().then(text=>window.richSelectedCopied=text==='Serendipity');`)
			browser.wait(`window.richSelectedCopied===true && editingNoteId===dictNoteID`)
			browser.script(`richEdit.editor.chain().focus().setTextSelection(1).run();window.expectedFullCopy=document.getElementById('edit-title-'+dictNoteID).value+'\n\n'+richEdit.editor.view.dom.innerText.trim();`)
			click(".is-editing .edit-copy")
			browser.script(`navigator.clipboard.readText().then(text=>window.richFullCopied=text===expectedFullCopy);`)
			browser.wait(`window.richFullCopied===true`)
			browser.script(`const input=document.getElementById('edit-title-'+dictNoteID);input.focus();input.setSelectionRange(0,10);`)
			click(".is-editing .edit-copy")
			browser.script(`navigator.clipboard.readText().then(text=>window.titleSelectedCopied=text==='Dictionary');`)
			browser.wait(`window.titleSelectedCopied===true`)
			// Copy any selection without opening Dictionary, and keep editing active.
			browser.script(`const p=richEdit.editor.view.dom.querySelector('p');const range=document.createRange();range.selectNodeContents(p);const selection=getSelection();selection.removeAllRanges();selection.addRange(range);window.expectedCopy=selection.toString();p.dispatchEvent(new MouseEvent('contextmenu',{bubbles:true,cancelable:true,clientX:20,clientY:100}));`)
			browser.wait(`!document.getElementById('note-context-menu').hidden`)
			click("#note-context-copy")
			browser.wait(`document.getElementById('note-action-toast').textContent==='Copied' && !document.getElementById('dictionary-dialog').open && editingNoteId===dictNoteID`)
			browser.script(`navigator.clipboard.readText().then(text=>window.copyCorrect=text===expectedCopy);`)
			browser.wait(`window.copyCorrect===true`)
			browser.script(`const e=new MouseEvent('contextmenu',{bubbles:true,cancelable:true,shiftKey:true});richEdit.editor.view.dom.dispatchEvent(e);if(e.defaultPrevented||!document.getElementById('note-context-menu').hidden)throw new Error('Shift right-click must preserve native menu');`)
			browser.script(`document.getElementById('spelling-open').click();`)
			click("#spelling-enabled")
			browser.script(`if(richEdit.editor.view.dom.spellcheck || document.getElementById('content').spellcheck || document.getElementById('title').spellcheck)throw new Error('Spellcheck not disabled');`)
			click("#spelling-close")
			browser.script(`richEdit.editor.chain().focus().setTextSelection({from:1,to:12}).run();`)
			if width == 320 {
				browser.wait(`!document.getElementById('note-selection-actions').hidden && document.querySelector('.rich-context-menu').hidden`)
				browser.script(`const r=document.getElementById('note-selection-actions').getBoundingClientRect(),footer=document.querySelector('.note-card.is-editing .editor-actions').getBoundingClientRect();if(r.left<0||r.right>innerWidth||r.bottom>footer.top||r.top<innerHeight/2)throw new Error('Selection actions cover editor controls');`)
				click("#dictionary-selection")
			} else {
				browser.wait(`!document.querySelector('.rich-context-menu').hidden && Boolean(document.querySelector('[data-rich-dictionary]'))`)
				browser.script(`const menu=document.querySelector('.rich-context-menu').getBoundingClientRect(); if(menu.left<0 || menu.right>innerWidth) throw new Error('Selection toolbar overflows');`)
				click("[data-rich-dictionary]")
			}
			browser.wait(`document.getElementById('dictionary-dialog').open && document.getElementById('dictionary-word').value==='serendipity' && document.querySelectorAll('#dictionary-result li').length>0`)
			browser.script(`if(editingNoteId!==dictNoteID || !document.documentElement.classList.contains('note-edit-focus')) throw new Error('Dictionary closed the active editor');`)
			click("#dictionary-close")
			if width == 320 {
				browser.script(`let from;richEdit.editor.state.doc.descendants((node,pos)=>{if(node.isText&&node.text.includes('Children'))from=pos+node.text.indexOf('Children');});richEdit.editor.chain().focus().setTextSelection({from,to:from+8}).run();window.beforeSelectionIgnore=richEdit.getMarkdown();`)
				browser.wait(`!document.getElementById('note-selection-actions').hidden && !document.getElementById('selection-ignore').disabled`)
				click("#selection-ignore")
				browser.wait(`!spellingBusy && ignoredSpellingWords.includes('children')`)
				browser.script(`if(editingNoteId!==dictNoteID||richEdit.getMarkdown()!==beforeSelectionIgnore)throw new Error('Bottom ignore closed or changed the note');`)
			}
			browser.script(`updateNote(dictNoteID);`)
			browser.wait(`editingNoteId===null`)
			click("#view-toggle")
			browser.script(`document.getElementById('spelling-open').scrollIntoView({block:'center'});`)
			browser.wait(`document.getElementById('spelling-open').getBoundingClientRect().height>0 && document.getElementById('spelling-open').getBoundingClientRect().bottom<=innerHeight`)
			browser.wait(`document.getElementById('view-menu').getBoundingClientRect().left>=0`)
			click("#spelling-open")
			browser.wait(`document.getElementById('spelling-dialog').open && !document.getElementById('spelling-enabled').checked && spellingReady && !spellingBusy`)
			browser.script(`document.getElementById('spelling-name').value='New York';document.getElementById('spelling-name-kind').value='place';document.getElementById('spelling-name-form').requestSubmit();`)
			browser.wait(`spellingNames.length===1 && document.getElementById('spelling-names-list').textContent.includes('New York')`)
			browser.script(`document.getElementById('spelling-name').value='Sriniously';document.getElementById('spelling-name-kind').value='person';document.getElementById('spelling-name-form').requestSubmit();`)
			browser.wait(`spellingNames.length===2`)
			click("#spelling-close")
			browser.navigate(server.URL)
			browser.wait(`!notesLoading && !document.getElementById('app-shell').hidden && Boolean(window.GnotesDictionary)`)
			browser.script(`if(spellcheckEnabled || !ignoredSpellingWords.includes('serendipity') || spellingNames.length!==2)throw new Error('Spelling preferences did not persist'); const host=document.createElement('div');document.body.append(host); const editor=GnotesRichEditor.mount(host,'New **York**, Sriniously, and Yorktown. Serendi**pity**.',()=>{throw new Error('Settings changed note content')});editor.setSpelling(true,ignoredSpellingWords,spellingNames);const ignored=[...host.querySelectorAll('[data-spelling-ignored]')].map(n=>n.textContent).join('');if(!ignored.includes('New York')||!ignored.includes('Sriniously')||ignored.includes('Yorktown')||!ignored.includes('Serendipity'))throw new Error('Names/words not ignored across formatting');editor.destroy();host.remove();`)
			browser.script(`document.getElementById('account-control').open=true;`)
			click("#dictionary-open")
			click("#dictionary-saved-tab")
			browser.wait(`document.querySelectorAll('#dictionary-word-list li').length===2`)
			browser.script(`document.getElementById('dictionary-filter').value='engine';document.getElementById('dictionary-filter').dispatchEvent(new Event('input'));`)
			browser.wait(`document.querySelectorAll('#dictionary-word-list li').length===1 && document.querySelector('[data-lookup-word="engineering"]')`)
			click(`[data-remove-word="engineering"]`)
			browser.wait(`document.getElementById('dictionary-list-status').textContent==='No saved words match.'`)
			click("#dictionary-lookup-tab")
			browser.script(`document.getElementById('dictionary-word').value='children';document.getElementById('dictionary-lookup-form').requestSubmit();`)
			browser.wait(`document.querySelector('#dictionary-result h3')?.textContent==='children' && document.getElementById('dictionary-result').textContent.includes('Definitions for child')`)
			click("#dictionary-close")
			browser.script(`document.getElementById('account-control').open=true;`)
			click("#logout-button")
			browser.wait(`!document.getElementById('auth-screen').hidden && !document.getElementById('dictionary-dialog').open && document.getElementById('dictionary-word').value==='' && document.querySelectorAll('#dictionary-word-list li').length===0`)
			browser.script(`document.getElementById('auth-username').value='other'; document.getElementById('auth-password').value='original password'; document.getElementById('auth-form').requestSubmit();`)
			browser.wait(`!document.getElementById('app-shell').hidden`)
			browser.script(`if(!spellcheckEnabled || ignoredSpellingWords.length || spellingNames.length)throw new Error('Spelling preferences leaked to another account');`)
			browser.script(`GnotesDictionary.open('serendipity');`)
			browser.wait(`document.querySelector('#dictionary-result h3')?.textContent==='serendipity' && document.getElementById('dictionary-save').textContent==='Save word'`)
			click("#dictionary-saved-tab")
			browser.wait(`document.getElementById('dictionary-list-status').textContent==='No saved words yet.'`)
		})
	}
}
